using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Crusaders.Mainframe.Api.Services;

namespace Crusaders.Mainframe.Tests;

/// <summary>
/// The server half of the <c>membercode/</c> corpus: every case of every file whose manifest
/// entry names <c>csharp</c>, executed, and counted against the manifest per section.
///
/// <para>
/// The corpus was generated by Python's own <c>hmac</c>, <c>hashlib</c> and <c>zoneinfo</c>
/// (<c>src/iot/tools/membercode_vectors.py</c>), so a C# primitive agreeing with it agrees with
/// an implementation that is not itself — the firmware, the phone and this server are each held
/// to that one reference rather than to each other.
/// </para>
///
/// <para>
/// Three sections describe what a DEVICE does with what it is sent (<c>roster.decide</c>,
/// <c>codesync.apply</c>, <c>gate.offline</c>). The server does not decide scans offline, so those
/// are executed through a deliberately small test-side model of the device (<see cref="DeviceModel"/>)
/// built on the server's own parsers — which is what makes them worth running here: every element
/// the model accepts is one the server's validators accept, and the ring the model builds from a
/// body is keyed by the server's own derivations.
/// </para>
/// </summary>
public partial class MemberCodeCorpusTests
{
    internal static string CorpusRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null)
        {
            var candidate = Path.Combine(dir.FullName, "src", "contracts", "device-protocol", "membercode");
            if (Directory.Exists(candidate)) return candidate;
            dir = dir.Parent;
        }

        throw new DirectoryNotFoundException(
            "src/contracts/device-protocol/membercode was not found above the test binary; a missing corpus must fail loudly.");
    }

    internal static JsonElement Load(string file) =>
        JsonDocument.Parse(File.ReadAllText(Path.Combine(CorpusRoot(), file))).RootElement;

    private static readonly JsonElement Manifest = Load("manifest.json");

    internal static int Declared(string file, string section) =>
        Manifest.GetProperty("files").GetProperty(file).GetProperty("case_count").GetProperty(section).GetInt32();

    internal static IEnumerable<JsonElement> Cases(JsonElement doc, string section) => doc.GetProperty(section).EnumerateArray();

    internal static byte[] Hex(JsonElement e, string prop) => Convert.FromHexString(e.GetProperty(prop).GetString()!);

    internal static string Str(JsonElement e, string prop) => e.GetProperty(prop).GetString()!;

    /// <summary>The files this reader must execute are exactly the ones the manifest says <c>csharp</c> reads.</summary>
    [Fact]
    public void The_manifest_names_exactly_the_files_this_suite_reads()
    {
        var mine = Manifest.GetProperty("files").EnumerateObject()
            .Where(f => f.Value.GetProperty("read_by").EnumerateArray().Any(r => r.GetString() == "csharp"))
            .Select(f => f.Name)
            .Order()
            .ToList();

        Assert.Equal(
            new[] { "clubday.json", "codesync.json", "derivation.json", "gate.json", "hkdf.json", "hmac.json",
                    "http.json", "payfor.json", "roster.json", "sha256.json", "token.json", "totp.json" },
            mine);
    }

    // ---- Primitives ---------------------------------------------------------------------------

    [Fact]
    public void Sha256_matches_every_vector()
    {
        var doc = Load("sha256.json");
        var executed = 0;
        foreach (var c in Cases(doc, "cases"))
        {
            var message = Hex(c, "message_hex");
            var repeat = c.GetProperty("repeat").GetInt32();
            using var sha = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
            for (var i = 0; i < repeat; i++) sha.AppendData(message);
            Assert.Equal(Str(c, "digest_hex"), Convert.ToHexStringLower(sha.GetHashAndReset()));
            executed++;
        }
        Assert.Equal(Declared("sha256.json", "cases"), executed);
    }

    [Fact]
    public void Hmac_matches_every_vector()
    {
        var doc = Load("hmac.json");
        var executed = 0;
        foreach (var c in Cases(doc, "cases"))
        {
            var mac = HMACSHA256.HashData(Hex(c, "key_hex"), Hex(c, "data_hex"));
            if (c.TryGetProperty("truncate_bytes", out var t)) mac = mac[..t.GetInt32()];
            Assert.Equal(Str(c, "mac_hex"), Convert.ToHexStringLower(mac));
            executed++;
        }
        Assert.Equal(Declared("hmac.json", "cases"), executed);
    }

    [Fact]
    public void Hkdf_matches_every_vector()
    {
        var doc = Load("hkdf.json");
        var executed = 0;
        foreach (var c in Cases(doc, "cases"))
        {
            var okm = MemberCodeMath.Hkdf(Hex(c, "ikm_hex"), Hex(c, "salt_hex"), Hex(c, "info_hex"), c.GetProperty("length").GetInt32());
            Assert.Equal(Str(c, "okm_hex"), Convert.ToHexStringLower(okm));
            executed++;
        }
        Assert.Equal(Declared("hkdf.json", "cases"), executed);
    }

    [Fact]
    public void Totp_matches_every_vector()
    {
        var doc = Load("totp.json");
        var executed = 0;
        foreach (var c in Cases(doc, "cases"))
        {
            var unix = c.GetProperty("unix").GetInt64();
            var step = c.GetProperty("step").GetInt64();
            Assert.Equal(step, MemberCodeMath.StepOf(DateTimeOffset.FromUnixTimeSeconds(unix)));

            var digits = c.GetProperty("digits").GetInt32();
            var code = MemberCodeMath.Digits(MemberCodeMath.Hotp(Hex(c, "key_hex"), step, digits), digits);
            Assert.Equal(Str(c, "code"), code);
            executed++;
        }
        Assert.Equal(Declared("totp.json", "cases"), executed);
    }

    // ---- Derivations ---------------------------------------------------------------------------

    [Fact]
    public void Derivation_chain_master_to_token_matches_every_vector()
    {
        var doc = Load("derivation.json");
        var master = Hex(doc, "fixture_master_key_hex");
        Assert.Equal(Encoding.ASCII.GetString(MemberCodeMath.HkdfSalt), Str(doc, "hkdf_salt_ascii"));
        Assert.Equal(MemberCodeMath.KdayLabelPrefix, Str(doc, "kday_label_prefix_ascii"));

        var executed = 0;
        foreach (var c in Cases(doc, "cases"))
        {
            var tenant = Guid.Parse(Str(c, "tenant_id"));
            var user = Guid.Parse(Str(c, "user_id"));
            var generation = c.GetProperty("generation").GetInt32();

            Assert.Equal(Str(c, "hkdf_info_ascii"), MemberCodeMath.SecretInfo(tenant, user, generation));
            var secret = MemberCodeMath.MemberSecret(master, tenant, user, generation);
            Assert.Equal(Str(c, "member_secret_hex"), Convert.ToHexStringLower(secret));

            var refValue = c.GetProperty("ref_value").GetInt32();
            Assert.Equal(Str(c, "ref"), MemberCodeMath.RefText(refValue));

            var zone = MemberCodeMath.ZoneOf(Str(c, "tz"));
            foreach (var s in c.GetProperty("steps").EnumerateArray())
            {
                var step = s.GetProperty("step").GetInt64();
                Assert.Equal(step, MemberCodeMath.StepOf(DateTimeOffset.FromUnixTimeSeconds(s.GetProperty("unix").GetInt64())));
                var day = MemberCodeMath.ClubDay(step, zone);
                Assert.Equal(Str(s, "club_day"), day);

                var kday = MemberCodeMath.Kday(secret, day);
                Assert.Equal(Str(s, "kday_hex"), Convert.ToHexStringLower(kday));
                Assert.Equal(Str(s, "kday_b64url"), MemberCodeMath.Base64Url(kday));
                Assert.Equal(Str(s, "on"), MemberCodeMath.On(secret, step));
                Assert.Equal(Str(s, "off"), MemberCodeMath.Off(kday, step));
                Assert.Equal(Str(s, "token"), MemberCodeMath.Token(Str(c, "ref"), secret, step, zone));
            }
            executed++;
        }
        Assert.Equal(Declared("derivation.json", "cases"), executed);
    }

    [Fact]
    public void Club_day_and_its_step_range_match_every_vector()
    {
        var doc = Load("clubday.json");
        var executed = 0;
        foreach (var c in Cases(doc, "cases"))
        {
            var zone = MemberCodeMath.ZoneOf(Str(c, "tz"));
            Assert.Equal(Str(c, "tz"), zone.Id);
            var step = c.GetProperty("step").GetInt64();
            Assert.Equal(step, MemberCodeMath.StepOf(DateTimeOffset.FromUnixTimeSeconds(c.GetProperty("unix").GetInt64())));
            Assert.Equal(Str(c, "club_day"), MemberCodeMath.ClubDay(step, zone));

            var (first, end) = MemberCodeMath.DayRange(step, zone);
            Assert.Equal(c.GetProperty("day_first_step").GetInt64(), first);
            Assert.Equal(c.GetProperty("day_end_step").GetInt64(), end);
            Assert.Equal(c.GetProperty("day_steps").GetInt64(), end - first);
            executed++;
        }
        Assert.Equal(Declared("clubday.json", "cases"), executed);
    }

    // ---- The token ----------------------------------------------------------------------------

    [Fact]
    public void Token_encode_and_decode_match_every_vector()
    {
        var doc = Load("token.json");
        Assert.Equal(MemberCodeMath.TokenLength, doc.GetProperty("token_len").GetInt32());

        var encoded = 0;
        foreach (var c in Cases(doc, "encode"))
        {
            var refText = MemberCodeMath.RefText(c.GetProperty("ref_value").GetInt32());
            Assert.Equal(Str(c, "ref"), refText);
            Assert.Equal(Str(c, "token"), MemberCodeMath.Version + refText + Str(c, "on") + Str(c, "off"));
            encoded++;
        }
        Assert.Equal(Declared("token.json", "encode"), encoded);

        var decoded = 0;
        foreach (var c in Cases(doc, "decode"))
        {
            var parsed = MemberCodeMath.Parse(Str(c, "input"));
            var id = Str(c, "id");
            if (c.GetProperty("ok").GetBoolean())
            {
                Assert.True(parsed is not null, $"decode '{id}' should parse");
                Assert.Equal(Str(c, "ref"), parsed!.Ref);
                Assert.Equal(c.GetProperty("ref_value").GetInt32(), parsed.RefValue);
                Assert.Equal(Str(c, "on"), parsed.On);
                Assert.Equal(Str(c, "off"), parsed.Off);
            }
            else
            {
                Assert.True(parsed is null, $"decode '{id}' should be refused ({Str(c, "why")})");
            }
            decoded++;
        }
        Assert.Equal(Declared("token.json", "decode"), decoded);
    }

    /// <summary>Length alone separates the two families: no legacy code is nineteen characters.</summary>
    [Fact]
    public void No_legacy_code_is_v1_shaped()
    {
        Assert.NotEqual(Crusaders.Mainframe.Api.Domain.AccessCode.Length, MemberCodeMath.TokenLength);
        Assert.False(MemberCodeMath.IsV1Shaped(AccessCodeService.NewCode()));
    }
}
